import React from 'react';
import { createPortal } from 'react-dom';
import FlightTooltip from './FlightTooltip';

const AvailabilityBadges = ({
  route,
  classes,
  date,
  flightData,
  cellPages,
  getFlightsForClassWithFilters,
  createEnhancedTooltip,
  activeTooltipRef
}) => {
  // Get background color for badge based on class and availability
  const getBackgroundColor = (classCode, available) => {
    if (!available) return 'transparent';

    // Class-specific colors
    switch (classCode) {
      case 'Y': // Economy
        return '#4CAF50';
      case 'W': // Premium Economy
        return '#2196F3';  
      case 'J': // Business
        return '#9C27B0';
      case 'F': // First
        return '#F44336';
      default:
        return '#9E9E9E';
    }
  };

  // Check if class should be shown as available
  const shouldShowAsAvailable = (classCode) => {
    // If route is not in flightData, it's not available
    if (!flightData || !flightData.routes || !flightData.routes[route]) {
      return false;
    }

    const routeData = flightData.routes[route];
    const dateData = routeData[date];

    // If date is not in routeData, it's not available
    if (!dateData) {
      return false;
    }

    // Check if the current class has available flights after filters
    const flights = getFlightsForClassWithFilters(route, classCode, date, dateData);
    return flights.length > 0;
  };

  // Handler for badge click to show tooltip
  const handleBadgeClick = (classCode, e) => {
    e.stopPropagation();

    // Get route data for this date
    if (!flightData || !flightData.routes || !flightData.routes[route]) {
      return;
    }

    const routeData = flightData.routes[route];
    const dateData = routeData[date];

    if (!dateData) {
      return;
    }

    // Get filtered flights for this class
    const flights = getFlightsForClassWithFilters(route, classCode, date, dateData);
    if (flights.length === 0) {
      return;
    }

    // Create tooltip data
    const tooltipData = createEnhancedTooltip(classCode, flights);

    // Create a new div for the tooltip
    const tooltipContainer = document.createElement('div');
    tooltipContainer.id = tooltipData.tooltipId;
    tooltipContainer.className = 'tooltip-container';

    // Position the tooltip near the clicked element
    const rect = e.currentTarget.getBoundingClientRect();

    tooltipContainer.style.position = 'absolute';
    tooltipContainer.style.left = `${rect.left}px`;
    tooltipContainer.style.top = `${rect.bottom + 5}px`;
    tooltipContainer.style.zIndex = '1000';

    // Add the tooltip to the document body
    document.body.appendChild(tooltipContainer);

    // Render the tooltip component into the container
    const closeTooltip = () => {
      if (document.body.contains(tooltipContainer)) {
        document.body.removeChild(tooltipContainer);
        activeTooltipRef.current = null;
      }
    };

    // Use createPortal to render the tooltip
    createPortal(
      <FlightTooltip
        flights={tooltipData.flights}
        classCode={tooltipData.classCode}
        isDirect={tooltipData.isDirect}
        closeTooltip={closeTooltip}
      />,
      tooltipContainer
    );
  };

  return (
    <div className="class-badges">
      {classes.map(classCode => {
        const isAvailable = shouldShowAsAvailable(classCode);
        const backgroundColor = getBackgroundColor(classCode, isAvailable);

        return (
          <span 
            key={classCode}
            className={`class-badge ${isAvailable ? 'available' : 'unavailable'}`}
            style={{ backgroundColor }}
            onClick={isAvailable ? (e) => handleBadgeClick(classCode, e) : undefined}
          >
            {classCode}
          </span>
        );
      })}
    </div>
  );
};

export default AvailabilityBadges;
